import {familyDashboard} from './family-admin.mjs';
import {subscriptionInput} from './subscriptions.mjs';
export function bytesLabel(value){return Number(value||0)<1048576?(Number(value||0)/1024).toFixed(1)+' كيلوبايت':(Number(value||0)/1048576).toFixed(2)+' ميجابايت'}
export function tenantOperations({t,element,button,busy,rpc,toast,reload}){
 const box=element('section',undefined,'tenant-operations');box.append(element('h4','الدخول والصيانة والاستهلاك'));const access=t.login_access==='blocked'?'الدخول موقوف':t.login_access==='suspended'&&Date.parse(t.login_suspended_until)>Date.now()?'الدخول معلّق حتى '+new Date(t.login_suspended_until).toLocaleString('ar-SA'):'الدخول متاح';box.append(element('p',access));
 function confirm(title,message,fn){const d=element('dialog');d.append(element('h3',title),element('p',message));const accept=button('تأكيد',()=>busy(accept,async()=>{await fn();d.close();d.remove();await reload()}),'primary');d.append(accept,button('إلغاء',()=>{d.close();d.remove()}));document.body.append(d);d.showModal()}
 const actions=element('div',undefined,'operation-buttons');actions.append(button('⏸ تعليق الدخول',()=>{const d=element('dialog');d.append(element('h3','تعليق الدخول مؤقتًا'),element('p','سيُمنع جميع أعضاء الكيان من الدخول حتى الموعد التالي، وتبقى البيانات محفوظة. التوقيت: الرياض.'));const until=element('input');until.type='datetime-local';until.value=subscriptionInput(new Date(Date.now()+86400000).toISOString());until.setAttribute('aria-label','نهاية التعليق');const apply=button('تأكيد التعليق',()=>busy(apply,async()=>{const date=new Date(until.value+'+03:00');if(!Number.isFinite(+date)||+date<=Date.now())throw Error('اختر موعدًا مستقبليًا.');await rpc('platform_action',{action:'login_access',data:{id:t.id,mode:'suspended',until:date.toISOString()}});d.close();d.remove();await reload()}),'secondary');d.append(until,apply,button('إلغاء',()=>{d.close();d.remove()}));document.body.append(d);d.showModal()}),button('⛔ إيقاف الدخول',()=>confirm('إيقاف الدخول','سيُمنع الدخول إلى '+t.name+' حتى تعيد فتحه. البيانات محفوظة.',()=>rpc('platform_action',{action:'login_access',data:{id:t.id,mode:'blocked'}})),'danger'),button('▶ إتاحة الدخول',()=>confirm('إتاحة الدخول',t.name,()=>rpc('platform_action',{action:'login_access',data:{id:t.id,mode:'allowed'}}))));box.append(actions);
 const usage=element('div',undefined,'tenant-usage');const measure=button('◴ قياس استهلاك الكيان',()=>busy(measure,async()=>{const u=await rpc('platform_action',{action:'usage',data:{id:t.id}});usage.replaceChildren(element('p','السجلات: نحو '+bytesLabel(u.row_bytes_estimate)),element('p','الصور والملفات: '+bytesLabel(u.file_bytes)+' · '+u.files+' ملف'),element('p',u.users+' عضو · '+u.news+' خبر · '+u.messages+' رسالة · '+u.groups+' مجموعة'),element('small','حجم السجلات تقديري دون تخصيص الفهارس والمساحة المشتركة. حدود الاستضافة مشتركة بين الكيانات.'))}),'secondary');box.append(measure,usage);
 const controls=element('div');box.append(button('ضوابط الاستثناءات وطلبات الصيانة',()=>busy(null,async()=>{const data=await rpc('platform_action',{action:'operations',data:{id:t.id}});controls.replaceChildren();const f=element('form');f.append(element('h4','استثناءات الدردشة الخاصة'));function check(label,value){const l=element('label',label,'inline'),i=element('input');i.type='checkbox';i.checked=!!value;l.prepend(i);f.append(l);return i}const trusted=check('التواصل بين المعرّف والعضو بعد قبول التعريف',data.trusted),kinship=check('التواصل بين الأقارب بعد تأكيد القرابة',data.kinship);const relations=[];for(const r of data.relations)relations.push([r.code,check(r.label,r.allowed)]);const save=element('button','حفظ ضوابط التواصل','secondary');f.append(save);f.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{await rpc('platform_action',{action:'chat_policy',data:{id:t.id,trusted:trusted.checked,kinship:kinship.checked,relations:relations.filter(([,i])=>i.checked).map(([c])=>c)}});toast('حُفظت الضوابط.')})};controls.append(f,element('h4','دخول الصيانة بموافقة مدير العائلة'),element('p','تصريح محدد بالساعات يوافق عليه مدير العائلة ويستطيع إلغاءه فورًا؛ يتيح إدارة الأعضاء والإعدادات والأخبار عبر لوحة الصيانة، دون قراءة الرسائل الخاصة.'));
 const hours=element('input');hours.type='number';hours.min=1;hours.max=72;hours.value=2;hours.setAttribute('aria-label','مدة الصيانة المطلوبة بالساعات');controls.append(element('label','المدة المطلوبة بالساعات (1–72)'),hours);const reason=element('input');reason.placeholder='سبب طلب الصيانة';reason.maxLength=1000;reason.setAttribute('aria-label','سبب طلب الصيانة');const request=button('إرسال طلب موافقة للصيانة',()=>busy(request,async()=>{await rpc('platform_action',{action:'maintenance_request',data:{id:t.id,reason:reason.value.trim(),hours:Number(hours.value)}});toast('أرسل الطلب إلى مدير الكيان.');controls.replaceChildren();}),'secondary');controls.append(reason,request);for(const m of data.maintenance){const row=element('div',undefined,'maintenance-request');row.append(element('strong',m.reason),element('small',({pending:'بانتظار موافقة مدير الكيان',approved:'موافق عليه',rejected:'مرفوض',revoked:'ملغى'}[m.status]||m.status)+(m.expires_at?' · حتى '+new Date(m.expires_at).toLocaleString('ar-SA'):'')));if(m.status==='approved'&&Date.parse(m.expires_at)>Date.now())row.append(button('دخول الصيانة المصرّح',()=>familyDashboard({rpc,element,button,busy,toast,maintenance:m.id}),'primary'));controls.append(row)}}),'secondary'),controls);
 async function openMaintenance(m){const d=element('dialog',undefined,'maintenance-console'),content=element('div');d.append(element('h3','صيانة '+t.name),button('خروج من الصيانة',()=>{d.close();d.remove()}),content);document.body.append(d);d.showModal();let timer;async function refresh(){if(!d.isConnected||!d.open){clearInterval(timer);return}try{const info=await rpc('platform_action',{action:'maintenance_open',data:{id:t.id,request:m.id}});if(!d.isConnected)return;content.replaceChildren(element('p',info.scope),element('p','ينتهي التصريح: '+new Date(info.expires_at).toLocaleString('ar-SA')));for(const [key,label]of [['chat_enabled','الدردشة'],['private_chat_enabled','الخاص'],['restrict_gender_chat','فصل الجنسين'],['journalist_approval','موافقة أخبار الصحفي']])content.append(element('p',label+': '+(info.settings?.[key]?'مفعّل':'معطّل')));for(const post of info.news){const a=element('article',undefined,'card');a.append(element('h4',post.title),element('p',post.body));content.append(a)}}catch(e){content.replaceChildren(element('p',e.message));clearInterval(timer)}}await refresh();timer=setInterval(refresh,15000);d.addEventListener('close',()=>{clearInterval(timer);content.replaceChildren()});}
 return box;
}
export async function familyMaintenance({rpc,element,button,busy,toast}){
 const d=element('dialog',undefined,'family-maintenance');d.append(element('h3','طلبات صيانة المنصة'),element('p','حدد مدة الصيانة بالساعات. يتيح التصريح إدارة الأعضاء والإعدادات والأخبار، دون الرسائل الخاصة. يمكنك إلغاؤه فورًا.'),button('إغلاق',()=>{d.close();d.remove()}));const list=element('div');d.append(list);document.body.append(d);d.showModal();async function load(){const rows=await rpc('maintenance_action',{action:'list'});list.replaceChildren();for(const r of rows){const a=element('article',undefined,'maintenance-request');a.append(element('strong',r.reason),element('small',({pending:'طلب جديد',approved:'موافق عليه',rejected:'مرفوض',revoked:'ملغى'}[r.status])));for(const [action,label]of r.status==='pending'?[['approve','موافقة مع تحديد المدة'],['reject','رفض']]:r.status==='approved'?[['revoke','إلغاء التصريح']]:[]){const b=button(label,()=>{const c=element('dialog');c.append(element('h3',label),element('p',r.reason));const hours=element('input');hours.type='number';hours.min=1;hours.max=72;hours.value=r.requested_hours||2;hours.setAttribute('aria-label','مدة التصريح بالساعات');if(action==='approve')c.append(element('label','مدة التصريح بالساعات (1–72)'),hours);const yes=button('تأكيد',()=>busy(yes,async()=>{await rpc('maintenance_action',{action,payload:{id:r.id,hours:Number(hours.value)}});c.close();c.remove();await load();toast('حُفظ القرار.')}),'primary');c.append(yes,button('إلغاء',()=>{c.close();c.remove()}));document.body.append(c);c.showModal()},action==='approve'?'primary':'secondary');a.append(b)}list.append(a)}if(!rows.length)list.append(element('p','لا توجد طلبات صيانة.'))}await load();
}
